sp_widget.client_script:
api.controller = function() {
  var c = this;
  c.expanded = {};
  c.editing = {};
  c.editForms = {};
  c.submitting = {};
  c.actionMessages = {};

  function parseYmd(str) {
    if (!str) return null;
    var parts = String(str).substring(0, 10).split("-");
    if (parts.length !== 3) return null;
    return new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
  }

  function toLocalDateStr(val) {
    if (!val) return "";
    if (typeof val === "string") return val.substring(0, 10);
    if (val instanceof Date && !isNaN(val.getTime())) {
      var y = val.getFullYear();
      var m = ("0" + (val.getMonth() + 1)).slice(-2);
      var d = ("0" + val.getDate()).slice(-2);
      return y + "-" + m + "-" + d;
    }
    return String(val).substring(0, 10);
  }

  c.toggleDetails = function(id) {
    c.expanded[id] = !c.expanded[id];
  };

  c.canModify = function(res) {
    var st = res && res.status_value;
    return st !== "cancelled" && st !== "closed" && st !== "checked_out";
  };

  c.confirmReservation = function(res) {
    c.submitting[res.sys_id] = true;
    c.data.action = "confirm";
    c.data.reservationId = res.sys_id;
    c.server.update().then(function() {
      c.submitting[res.sys_id] = false;
      if (c.data.actionMessage) {
        c.actionMessages[res.sys_id] = { text: c.data.actionMessage, type: c.data.actionMessageType || "info" };
      }
    });
  };

  c.cancelReservation = function(res) {
    c.submitting[res.sys_id] = true;
    c.data.action = "cancel";
    c.data.reservationId = res.sys_id;
    c.server.update().then(function() {
      c.submitting[res.sys_id] = false;
      if (c.data.actionMessage) {
        c.actionMessages[res.sys_id] = { text: c.data.actionMessage, type: c.data.actionMessageType || "info" };
      }
      if (c.data.actionMessageType === "info") c.editing[res.sys_id] = false;
    });
  };

  c.startEdit = function(res) {
    if (c.editing[res.sys_id]) {
      c.editing[res.sys_id] = false;
      return;
    }
    c.editForms[res.sys_id] = {
      checkInDate: parseYmd(res.raw_check_in),
      checkOutDate: parseYmd(res.raw_check_out),
      adults: res.raw_adults,
      children: res.raw_children
    };
    c.editing[res.sys_id] = true;
  };

  c.cancelEdit = function(res) {
    c.editing[res.sys_id] = false;
  };

  c.saveUpdate = function(res) {
    var f = c.editForms[res.sys_id];
    if (!f) return;
    c.submitting[res.sys_id] = true;
    c.data.action = "update";
    c.data.reservationId = res.sys_id;
    c.data.editCheckIn = toLocalDateStr(f.checkInDate);
    c.data.editCheckOut = toLocalDateStr(f.checkOutDate);
    c.data.editAdults = f.adults;
    c.data.editChildren = f.children;
    c.server.update().then(function() {
      c.submitting[res.sys_id] = false;
      if (c.data.actionMessage) {
        c.actionMessages[res.sys_id] = { text: c.data.actionMessage, type: c.data.actionMessageType || "info" };
      }
      if (c.data.actionMessageType === "info") {
        c.editing[res.sys_id] = false;
      }
    });
  };
};

sp_widget.css:
.my-reservations-page {
  max-width: 1050px;
  margin: 0 auto;
  padding: 55px 25px 75px;
  color: #2a2d29;
  font-family: Arial, sans-serif;
}

.reservations-heading {
  text-align: center;
  margin-bottom: 40px;
}

.reservations-eyebrow,
.empty-eyebrow {
  color: #a8875b;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 3px;
}

.reservations-heading h1 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 42px;
  margin: 12px 0;
}

.reservations-heading p {
  color: #6f756f;
  font-size: 15px;
}

.reservation-list {
  display: grid;
  gap: 22px;
}

.reservation-card {
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 12px;
  padding: 25px;
  box-shadow: 0 5px 20px rgba(31, 58, 48, 0.05);
}

.reservation-top,
.reservation-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.reservation-label,
.reservation-dates span {
  display: block;
  color: #a8875b;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

.reservation-top h2 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 22px;
  margin: 7px 0 0;
}

.status-badge {
  background: #e8eee9;
  color: #1f3a30;
  padding: 8px 13px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
}

.reservation-room {
  display: flex;
  align-items: center;
  gap: 15px;
  margin: 25px 0;
}

.room-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  background: #e8eee9;
  color: #1f3a30;
  border-radius: 9px;
  font-size: 20px;
}

.reservation-room h3 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 20px;
  margin: 0 0 5px;
}

.reservation-room p {
  color: #6f756f;
  font-size: 12px;
  margin: 0;
}

.reservation-dates {
  display: flex;
  align-items: center;
  gap: 30px;
  padding: 20px 0;
  border-top: 1px solid #e7e1d4;
  border-bottom: 1px solid #e7e1d4;
}

.reservation-dates strong {
  display: block;
  margin-top: 9px;
  color: #2a2d29;
  font-size: 14px;
}

.date-divider {
  height: 35px;
  width: 1px;
  background: #e7e1d4;
}

.reservation-bottom {
  padding: 18px 0;
  color: #6f756f;
  font-size: 12px;
}

.reservation-bottom strong {
  color: #1f3a30;
  font-size: 18px;
}

.details-button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 13px 0 0;
  background: transparent;
  border: 0;
  border-top: 1px solid #e7e1d4;
  color: #1f3a30;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  text-align: left;
}

.reservation-details {
  margin-top: 18px;
  padding: 18px;
  background: #faf6ef;
  border-radius: 8px;
}

.reservation-details p {
  color: #6f756f;
  font-size: 13px;
  margin: 8px 0;
}

.reservation-details strong {
  color: #1f3a30;
}

.reservations-empty {
  max-width: 650px;
  margin: 35px auto 20px;
  padding: 55px 30px;
  text-align: center;
  background: #faf6ef;
  border: 1px solid #e7e1d4;
  border-radius: 14px;
}

.empty-icon {
  width: 70px;
  height: 70px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 22px;
  background: #e8eee9;
  color: #1f3a30;
  border-radius: 50%;
  font-size: 26px;
}

.reservations-empty h2 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 29px;
  margin: 12px 0;
}

.reservations-empty p {
  max-width: 450px;
  margin: 0 auto 25px;
  color: #6f756f;
  font-size: 14px;
  line-height: 1.8;
}

.browse-button {
  display: inline-block;
  background: #1f3a30;
  color: #ffffff !important;
  padding: 12px 20px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  text-decoration: none !important;
}

.browse-button:hover {
  background: #162a22;
}

@media (max-width: 600px) {
  .my-reservations-page {
    padding: 35px 15px 50px;
  }

  .reservations-heading h1 {
    font-size: 32px;
  }

  .reservation-dates {
    gap: 15px;
  }

  .reservation-top,
  .reservation-bottom {
    align-items: flex-start;
    flex-direction: column;
  }
}


.status-badge.status-cancelled { background: #f9e9e6; color: #9c3d31; }
.res-actions, .res-edit-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding: 12px 0 16px;
}
.res-btn {
  padding: 9px 14px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  border: none;
}
.res-btn:disabled { opacity: 0.6; cursor: not-allowed; }
.res-btn-confirm { background: #1f3a30; color: #ffffff; }
.res-btn-edit { background: #f3ede2; color: #1f3a30; border: 1px solid #d8ceb9; }
.res-btn-cancel { background: #f9e9e6; color: #9c3d31; border: 1px solid #ecc6bf; }
.res-btn-secondary { background: #efefef; color: #333333; }
.res-feedback {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  margin-bottom: 12px;
  border-radius: 6px;
  font-size: 13px;
}
.res-feedback.info { background: #e8eee9; color: #1f3a30; }
.res-feedback.error { background: #f9e9e6; color: #9c3d31; }
.res-edit-form {
  margin-bottom: 16px;
  padding: 18px;
  background: #faf6ef;
  border: 1px solid #e7e1d4;
  border-radius: 8px;
}
.res-edit-form h4 { margin: 0 0 12px; color: #1f3a30; font-family: Georgia, serif; }
.res-edit-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }
.res-edit-grid label { display: block; font-size: 12px; font-weight: 600; margin-bottom: 5px; color: #2a2d29; }
.res-edit-grid input { width: 100%; height: 38px; padding: 0 10px; border: 1px solid #e7e1d4; border-radius: 5px; background: #ffffff; box-sizing: border-box; }
@media (max-width: 600px) { .res-edit-grid { grid-template-columns: 1fr; } }

sp_widget.script:
(function() {
  data.actionMessage = "";
  data.actionMessageType = "";
  data.actionResId = "";

  var userId = gs.getUserID();
  var userEmail = (gs.getUser().getEmail() || "").toLowerCase().trim();

  if (input && input.action && input.reservationId && gs.isLoggedIn()) {
    var resUtil = new x_2206701_hotel_0.ReservationUtils();
    var pricingUtil = new x_2206701_hotel_0.PricingUtils();
    data.actionResId = input.reservationId;

    var target = new GlideRecord("x_2206701_hotel_0_scheduled_reservations");
    var ownsRecord = false;
    if (target.get(input.reservationId)) {
      var recUser = target.getValue("registered_user") || "";
      var recEmail = (target.getValue("guest_email") || "").toLowerCase().trim();
      ownsRecord = (recUser === userId) || (userEmail && recEmail === userEmail);
    }

    if (!ownsRecord) {
      data.actionMessage = "You are not authorized to modify this reservation.";
      data.actionMessageType = "error";
    } else if (input.action === "confirm") {
      var cRes = resUtil.confirmReservation(target.getUniqueValue());
      data.actionMessage = cRes.ok ? "Reservation confirmed successfully." : (cRes.message || "Unable to confirm reservation.");
      data.actionMessageType = cRes.ok ? "info" : "error";
    } else if (input.action === "cancel") {
      var canRes = resUtil.cancelReservation(target.getUniqueValue());
      data.actionMessage = canRes.message;
      data.actionMessageType = canRes.ok ? "info" : "error";
    } else if (input.action === "update") {
      var st = target.getValue("reservation_status");
      if (st === "cancelled" || st === "closed" || st === "checked_out") {
        data.actionMessage = "Closed or cancelled reservations cannot be modified.";
        data.actionMessageType = "error";
      } else {
        var cin = String(input.editCheckIn || "").substring(0, 10);
        var cout = String(input.editCheckOut || "").substring(0, 10);
        var dCheck = resUtil.validateDates(cin, cout);
        if (!dCheck.ok) {
          data.actionMessage = dCheck.message;
          data.actionMessageType = "error";
        } else {
          var roomId = target.getValue("room");
          var avail = pricingUtil.isRoomAvailable(roomId, cin, cout, target.getUniqueValue());
          if (!avail.available) {
            data.actionMessage = avail.reason || "Selected dates are not available.";
            data.actionMessageType = "error";
          } else {
            var adults = parseInt(input.editAdults, 10);
            var children = parseInt(input.editChildren, 10) || 0;
            var capOk = true;
            var capVal = 2;
            if (isNaN(adults) || adults < 1 || children < 0) {
              data.actionMessage = "Please enter valid guest counts (at least 1 adult).";
              data.actionMessageType = "error";
              capOk = false;
            } else {
              var roomRec = new GlideRecord("x_2206701_hotel_0_rooms");
              if (roomRec.get(roomId)) {
                capVal = parseInt(roomRec.getValue("capacity"), 10) || 2;
                if ((adults + children) > capVal) {
                  data.actionMessage = "Total guests exceed the maximum room capacity (" + capVal + ").";
                  data.actionMessageType = "error";
                  capOk = false;
                }
              }
            }
            if (capOk) {
              var nights = resUtil.calculateDays(cin, cout);
              var total = pricingUtil.calculateRoomTotal(roomId, nights, cin);
              target.setValue("check_in_date", cin);
              target.setValue("check_out_date", cout);
              target.setValue("number_of_days", nights);
              target.setValue("number_of_adults", adults);
              target.setValue("number_of_children", children);
              target.setValue("total_payment", total);
              target.update();
              data.actionMessage = "Reservation updated successfully.";
              data.actionMessageType = "info";
            }
          }
        }
      }
    }
  }

  data.reservations = [];
  if (gs.isLoggedIn()) {
    var gr = new GlideRecord("x_2206701_hotel_0_scheduled_reservations");
    var q = gr.addQuery("registered_user", userId);
    if (userEmail) {
      q.addOrCondition("guest_email", gs.getUser().getEmail());
    }
    gr.orderByDesc("sys_created_on");
    gr.query();
    while (gr.next()) {
      data.reservations.push({
        sys_id: gr.getUniqueValue(),
        number: gr.getValue("number") || gr.getDisplayValue("number"),
        status: gr.getDisplayValue("reservation_status"),
        status_value: gr.getValue("reservation_status"),
        room: gr.getDisplayValue("room"),
        room_id: gr.getValue("room"),
        check_in: gr.getDisplayValue("check_in_date"),
        check_out: gr.getDisplayValue("check_out_date"),
        raw_check_in: gr.getValue("check_in_date"),
        raw_check_out: gr.getValue("check_out_date"),
        adults: gr.getDisplayValue("number_of_adults"),
        children: gr.getDisplayValue("number_of_children"),
        raw_adults: parseInt(gr.getValue("number_of_adults"), 10) || 1,
        raw_children: parseInt(gr.getValue("number_of_children"), 10) || 0,
        days: gr.getDisplayValue("number_of_days"),
        total: gr.getDisplayValue("total_payment"),
        guest_name: gr.getDisplayValue("guest_name"),
        guest_email: gr.getDisplayValue("guest_email")
      });
    }
  }
})();
